<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(15, 23, 42, 0.92);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5eefb;
        --muted: #94a3b8;
        --accent: #7c3aed;
        --accent-strong: #8b5cf6;
        --input: rgba(15, 23, 42, 0.75);
        --input-border: rgba(148, 163, 184, 0.24);
        --error: #fda4af;
        --success-bg: rgba(34, 197, 94, 0.12);
        --success-text: #bbf7d0;
        --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.24), transparent 34%),
          linear-gradient(180deg, #111827 0%, var(--bg) 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .page-shell {
        width: min(100%, 680px);
      }

      .support-card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        padding: 32px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(12px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 6px 12px;
        border-radius: 999px;
        background: rgba(124, 58, 237, 0.12);
        color: #d8b4fe;
        font-size: 0.85rem;
        font-weight: 600;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 18px 0 12px;
        font-size: clamp(2rem, 4vw, 2.7rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 28px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
      }

      input {
        width: 100%;
        border: 1px solid var(--input-border);
        border-radius: 14px;
        background: var(--input);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        outline: none;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        border-color: rgba(139, 92, 246, 0.85);
        box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.18);
      }

      .helper-text {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .validation-message {
        min-height: 1.2em;
        color: var(--error);
        font-size: 0.92rem;
      }

      .field-invalid {
        border-color: rgba(244, 114, 182, 0.9);
        box-shadow: 0 0 0 4px rgba(244, 114, 182, 0.12);
      }

      .submit-row {
        display: flex;
        align-items: center;
        gap: 16px;
        flex-wrap: wrap;
        margin-top: 8px;
      }

      button {
        border: 0;
        border-radius: 14px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        box-shadow: 0 14px 32px rgba(124, 58, 237, 0.28);
        cursor: pointer;
        transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(124, 58, 237, 0.34);
        filter: brightness(1.04);
      }

      button:focus-visible {
        outline: 3px solid rgba(196, 181, 253, 0.8);
        outline-offset: 3px;
      }

      .status-message {
        min-height: 1.4em;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .status-message.success {
        color: var(--success-text);
        background: var(--success-bg);
        border: 1px solid rgba(74, 222, 128, 0.18);
        border-radius: 12px;
        padding: 10px 12px;
      }

      @media (max-width: 640px) {
        .support-card {
          padding: 24px;
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const fieldConfigs = [
        {
          id: "fullName",
          name: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Jordan Lee",
          required: true
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          helperText: "Optional. Use digits with spaces, hyphens, or parentheses, for example (555) 123-4567.",
          required: false
        }
      ];

      const formState = {
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        errors: {
          fullName: "",
          email: "",
          phone: ""
        },
        submitted: false,
        successMessage: ""
      };

      function PageShell(children) {
        return `
          <main class="page-shell">
            <section class="support-card">
              ${children}
            </section>
          </main>
        `;
      }

      function SupportHeader() {
        return `
          <div class="eyebrow">Support team</div>
          <h1>Contact support</h1>
          <p class="intro">
            Tell us what you need and our support team will get back to you with the right next steps.
          </p>
        `;
      }

      function FormField(field) {
        const error = formState.errors[field.name];
        const value = escapeHtml(formState.values[field.name]);
        const helper = field.helperText
          ? `<div class="helper-text" id="${field.id}-helper">${field.helperText}</div>`
          : "";
        const describedBy = [field.helperText ? `${field.id}-helper` : "", `${field.id}-error`]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              value="${value}"
              placeholder="${field.placeholder}"
              ${field.required ? "required" : ""}
              aria-required="${field.required ? "true" : "false"}"
              aria-invalid="${error ? "true" : "false"}"
              aria-describedby="${describedBy}"
              class="${error ? "field-invalid" : ""}"
            />
            ${helper}
            <div class="validation-message" id="${field.id}-error" aria-live="polite">${error}</div>
          </div>
        `;
      }

      function SubmitRow() {
        return `
          <div class="submit-row">
            <button type="submit">Send message</button>
            <div class="status-message ${formState.successMessage ? "success" : ""}" id="form-status" aria-live="polite">
              ${formState.successMessage}
            </div>
          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <form id="support-form" novalidate>
            ${fieldConfigs.map(FormField).join("")}
            ${SubmitRow()}
          </form>
        `;
      }

      function App() {
        return PageShell(`${SupportHeader()}${SupportContactForm()}`);
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName") {
          if (!trimmedValue) return "Full name is required.";
          if (trimmedValue.length < 2) return "Enter your full name.";
          return "";
        }

        if (name === "email") {
          if (!trimmedValue) return "Email address is required.";
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address.";
        }

        if (name === "phone") {
          if (!trimmedValue) return "";
          const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
          return phonePattern.test(trimmedValue)
            ? ""
            : "Enter a valid phone number using digits and common separators.";
        }

        return "";
      }

      function validateForm() {
        const nextErrors = {};

        fieldConfigs.forEach((field) => {
          nextErrors[field.name] = validateField(field.name, formState.values[field.name]);
        });

        formState.errors = nextErrors;
        return Object.values(nextErrors).every((error) => !error);
      }

      function syncField(field) {
        const input = document.getElementById(field.id);
        const errorElement = document.getElementById(`${field.id}-error`);
        const error = formState.errors[field.name];

        input.value = formState.values[field.name];
        input.classList.toggle("field-invalid", Boolean(error));
        input.setAttribute("aria-invalid", error ? "true" : "false");
        errorElement.textContent = error;
      }

      function syncStatus() {
        const status = document.getElementById("form-status");
        status.textContent = formState.successMessage;
        status.className = `status-message ${formState.successMessage ? "success" : ""}`.trim();
      }

      function syncForm() {
        fieldConfigs.forEach(syncField);
        syncStatus();
      }

      function updateField(name, value, shouldValidate) {
        formState.values[name] = value;
        if (shouldValidate || formState.submitted || formState.errors[name]) {
          formState.errors[name] = validateField(name, value);
        }
        formState.successMessage = "";
        syncForm();
      }

      function attachFormEvents() {
        const form = document.getElementById("support-form");

        fieldConfigs.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("input", (event) => {
            updateField(field.name, event.target.value, false);
          });

          input.addEventListener("blur", (event) => {
            updateField(field.name, event.target.value, true);
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          formState.submitted = true;

          if (!validateForm()) {
            formState.successMessage = "";
            syncForm();
            return;
          }

          formState.successMessage = "Thanks. Your message is ready for the support team.";
          formState.errors = {
            fullName: "",
            email: "",
            phone: ""
          };
          syncForm();
        });
      }

      document.getElementById("app").innerHTML = App();
      attachFormEvents();
      syncForm();
    </script>
  </body>
</html>
